.topic-table { min-width:0; overflow:visible; } .topic-row { display:grid; grid-template-columns:minmax(0,1fr) 64px 76px 188px 64px; min-width:0; min-height:60px; padding:12px 0; gap:8px; border:0; border-bottom:1px solid var(--border-subtle); font-size:13px; }
