.cockpit-types { margin-top:24px; } .cockpit-types > div { display:grid; grid-template-columns:minmax(0,1fr) repeat(3,auto); align-items:center; gap:8px; min-height:48px; padding:8px 0; border:0; border-top:1px solid var(--border-subtle); font-size:12px; } .cockpit-types > p { padding:8px 0; font-size:13px; color:var(--text-secondary); }
